/**
 * Scratch page for T7 — every level, rendered by the real `TileMap` with a free camera.
 * Not part of the game; served at /tiles.html.
 *
 * It runs the same 25 Hz step the game does, so the hazards move at their shipped speeds
 * and the door opens in the six ticks `b.g()` takes. The camera can either be dragged
 * around by hand or handed to `Camera` with a fake ball, which is how the scroll anchor
 * and the 84px vertical bands get eyeballed.
 */
import { Application, Container, Graphics, Text, type Spritesheet } from 'pixi.js';

import { hdEnabled, loadSheet, sheetLabel } from './sheet.ts';

import { Camera, VIEW_HEIGHT, VIEW_WIDTH } from '../game/Camera.ts';
import { Door } from '../game/Door.ts';
import { Level, TILE_SIZE, type LevelJson } from '../game/Level.ts';
import { stepPlatforms } from '../game/MovingPlatform.ts';
import { TileMap } from '../game/TileMap.ts';
import { HUD_COLOUR } from '../game/Tiles.ts';

const LEVEL_COUNT = 11;
const TICK_MS = 40;
const ZOOM = 4;
/** Where the text under the 128x128 screen starts, in canvas pixels. */
const TEXT_TOP = 16 + 128 * ZOOM + 8;
/** Free-camera speed, pixels per tick. */
const PAN_SPEED = 6;

type Scene = {
  level: Level;
  door: Door;
  map: TileMap;
  camera: Camera;
  root: Container;
};

const held = new Set<string>();
let scene: Scene | null = null;
let follow = false;
/** Stand-in for the ball while `follow` is on: pinned to the camera's anchor and driven by the keys. */
let ballX = 0;
let ballY = 0;

async function loadLevel(id: number): Promise<LevelJson> {
  const name = String(id).padStart(3, '0');
  const response = await fetch(`levels/${name}.json`);
  if (!response.ok) throw new Error(`levels/${name}.json: ${response.status}`);
  return (await response.json()) as LevelJson;
}

function status(): string {
  if (!scene) return '';
  const { level, camera, door } = scene;
  return [
    `level ${String(level.id).padStart(2, '0')}`,
    `${level.width}x${level.height} tiles`,
    `cam ${Math.round(camera.x)},${Math.round(camera.y)}`,
    `door ${door.offset}/24${door.open ? ' open' : ''}`,
    `hazards ${level.platforms.length}`,
    follow ? 'follow' : 'free',
  ].join('   ');
}

async function main(): Promise<void> {
  const canvas = document.getElementById('tiles-canvas') as HTMLCanvasElement;
  const app = new Application();
  await app.init({ canvas, background: 0x14141a, resizeTo: window, antialias: false });

  // H3: the HD sheet by default, `?hd=0` for the pre-HD look.
  const hd = hdEnabled();
  const sheet: Spritesheet = await loadSheet(hd);

  const stage = new Container();
  stage.scale.set(ZOOM);
  stage.position.set(16, 16);
  app.stage.addChild(stage);

  const info = new Text({
    text: '',
    resolution: 2,
    style: { fill: 0xd0d0d8, fontFamily: 'monospace', fontSize: 12 },
  });
  info.position.set(16, TEXT_TOP);
  app.stage.addChild(info);

  const help = new Text({
    text: [
      'arrows / WASD pan     drag to pan     [ ] previous / next level',
      'F follow a fake ball at the scroll anchor     O open the door     R reset',
      `atlas: ${sheetLabel(hd)}`,
    ].join('\n'),
    resolution: 2,
    style: { fill: 0x8a8a96, fontFamily: 'monospace', fontSize: 12 },
  });
  help.position.set(16, TEXT_TOP + 24);
  app.stage.addChild(help);

  // Level JSON is fetched, so two quick presses would otherwise race each other's
  // teardown. Builds are queued, and `wanted` — not the live scene, which lags — is what
  // the next/previous keys step, so holding `]` walks the levels one at a time.
  let loading: Promise<void> = Promise.resolve();
  let wanted = 1;
  const show = (id: number): Promise<void> => {
    wanted = id;
    loading = loading.then(() => build(id)).catch((error: unknown) => console.error(error));
    return loading;
  };

  async function build(id: number): Promise<void> {
    scene?.map.destroy();
    scene?.root.destroy({ children: true });
    stage.removeChildren();

    const level = new Level(await loadLevel(id));
    const door = new Door();
    const map = new TileMap(level, sheet, { door });
    const camera = new Camera();

    ballX = level.spawn.x * TILE_SIZE + level.startBallSize / 2;
    ballY = level.spawn.y * TILE_SIZE + level.startBallSize / 2;
    camera.reset(level, ballX, ballY);

    const root = new Container();
    // The play area is 96 tall; the strip below it is the HUD `d.n()` paints over.
    root.addChild(map.view, map.front);
    const hud = new Graphics()
      .rect(0, VIEW_HEIGHT + 1, VIEW_WIDTH, 128 - VIEW_HEIGHT - 1)
      .fill(HUD_COLOUR);
    root.addChild(hud);

    // Clip the play area so a partly-visible tile at the edge does not spill into the HUD.
    // A mask belongs to one target, so the two layers get one each.
    for (const layer of [map.view, map.front]) {
      const mask = new Graphics().rect(0, 0, VIEW_WIDTH, VIEW_HEIGHT).fill(0xffffff);
      root.addChild(mask);
      layer.mask = mask;
    }

    stage.addChild(root);
    scene = { level, door, map, camera, root };
  }

  await show(1);

  window.addEventListener('keydown', (event) => {
    held.add(event.key.toLowerCase());
    const current = wanted;
    if (event.key === '[') void show(((current + LEVEL_COUNT - 2) % LEVEL_COUNT) + 1);
    if (event.key === ']') void show((current % LEVEL_COUNT) + 1);
    if (event.key.toLowerCase() === 'f') follow = !follow;
    if (event.key.toLowerCase() === 'r') void show(current);
    if (event.key.toLowerCase() === 'o') scene?.door.advance();
  });
  window.addEventListener('keyup', (event) => held.delete(event.key.toLowerCase()));

  let dragging = false;
  canvas.addEventListener('pointerdown', () => {
    dragging = true;
  });
  window.addEventListener('pointerup', () => {
    dragging = false;
  });
  window.addEventListener('pointermove', (event) => {
    if (!dragging || !scene) return;
    scene.camera.x -= event.movementX / ZOOM;
    scene.camera.y -= event.movementY / ZOOM;
  });

  const axis = (negative: string[], positive: string[]): number =>
    (positive.some((key) => held.has(key)) ? 1 : 0) -
    (negative.some((key) => held.has(key)) ? 1 : 0);

  let accumulator = 0;
  app.ticker.add((ticker) => {
    accumulator += ticker.deltaMS;
    while (accumulator >= TICK_MS) {
      accumulator -= TICK_MS;
      if (!scene) continue;
      stepPlatforms(scene.level);

      const dx = axis(['arrowleft', 'a'], ['arrowright', 'd']) * PAN_SPEED;
      const dy = axis(['arrowup', 'w'], ['arrowdown', 's']) * PAN_SPEED;
      if (follow) {
        ballX += dx;
        ballY += dy;
        scene.camera.follow(ballX, dx);
        scene.camera.followVertical(ballX, ballY);
      } else {
        scene.camera.x += dx;
        scene.camera.y += dy;
      }
    }

    if (!scene) return;
    scene.camera.x = Math.round(scene.camera.x);
    scene.camera.y = Math.round(scene.camera.y);
    scene.map.update(scene.camera.x, scene.camera.y);
    info.text = status();
  });
}

void main();
